SELECT MAX(CAST(SUBSTR(frameVersion, 1, 4) AS INTEGER)) - MIN(CAST(SUBSTR(frameVersion, 1, 4) AS INTEGER)) AS year_span
FROM cards
WHERE name = 'Tarmogoyf' AND frameVersion IS NOT NULL AND LENGTH(frameVersion) >= 4 AND frameVersion GLOB '[0-9][0-9][0-9][0-9]*';

SELECT COUNT(DISTINCT scryfallOracleId) AS release_promo_card_count
FROM cards
WHERE promoTypes LIKE '%release%';

